get(name, stream) {
        return this.authenticator.authenticate().then(auth => new Promise((resolve, reject) => {
            axios({
                method: 'GET',
                url: `${auth.url + this.urlSuffix}/${name}`,
                headers: {
                    'x-auth-token': auth.token
                },
                responseType: 'stream'
            }).then((response) => {
              response.data.on('end',  () => {
                resolve();
              });
              response.data.pipe(stream);
            }).catch(err => {
                reject(err);
            });
        }));
    }

async function task() {
	const argv = [...process.argv];
	const port = process.argv.pop();
	const command = process.argv.pop();

	switch (command) {
		case "kill":
			const result = await main.killAllProcessesOnPort(port);
			console.log(result.filter(item => !item.success).map(item => `Failed to kill process ${item.pid}`).join('\n'));
			break;
		case "list":
			const result = await main.listProcessesOnPort(port);
			console.log(result);
			break;
		default:
			console.error("Command not found");
	}
}

