function mergeParamIntoObject(res, key, value) {
    var tmpVal;

    var objectIndex = key.indexOf(".");
    if(objectIndex < 0) {
        if (typeof res[key] === "undefined" && key !== "heading" && key !== "point" && key !== "details") {
            if (value === 'true')
                value = true;
            else if (value === 'false')
                value = false;

            res[key] = value;
        } else {
            tmpVal = res[key];
            if (isArray(tmpVal)) {
                tmpVal.push(value);
            } else if (tmpVal) {
                res[key] = [tmpVal, value];
            } else {
                res[key] = [value];
            }
        }
        return res;
    }

    var newKey = key.substring(0, objectIndex);
    var subKey = key.substring(objectIndex + 1);

    if(newKey == "__proto__" || key == "constructor" || key == "prototype") return res;

    tmpVal = res[newKey];
    if(!tmpVal)
        tmpVal = {};

    res[newKey] = mergeParamIntoObject(tmpVal, subKey, value);
    return res;
}

