function parseURLParams(
        url: URL,
        dontParse: boolean = false,
        source: string = 'hash'): Object {
    const paramStr = source === 'search' ? url.search : url.hash;
    const params = {};
    const paramParts = (paramStr && paramStr.substr(1).split('&')) || [];

    if (source === 'hash' && paramParts.length === 1) {
        const firstParam = paramParts[0];

        if (firstParam.startsWith('/') && firstParam.split('&').length === 1) {
            return params;
        }
    }

    paramParts.forEach(part => {
        const param = part.split('=');
        const key = param[0];

        if (!key || blacklist.includes(key.split('.')[0])) {
            return;
        }

        let value;

        try {
            value = param[1];

            if (!dontParse) {
                const decoded = decodeURIComponent(value).replace(/\\&/, '&');

                value = decoded === 'undefined' ? undefined : Bourne.parse(decoded);
            }
        } catch (e) {
            reportError(
                e, `Failed to parse URL parameter value: ${String(value)}`);

            return;
        }
        params[key] = value;
    });

    return params;
}

function HueBridgeNode(config)
	{
		RED.nodes.createNode(this, config);

		const scope = this;
		const bridge = RED.nodes.getNode(config.bridge);

		this.connected = false;

		this.lastBridgeInformation = null;

		this.lastCommand = null;

		this.timeout = null;

		this.nodeActive = true;

		if(bridge == null)
		{
			this.status({fill: "red", shape: "ring", text: "hue-bridge.node.not-configured"});
			return false;
		}

		scope.status({fill: "grey", shape: "dot", text: "hue-bridge.node.connecting"});

		this.setInitialState = function()
		{
			scope.status({fill: "green", shape: "dot", text: "hue-bridge.node.connected"});
		}


		this.getBridgeInformation = async function(forceReload = false)
		{
			return new Promise(function(resolve, reject)
			{
				if(forceReload === true)
				{
					bridge.getBridgeInformation(true)
					.then(function(updated)
					{
						return scope.getBridgeInformation();
					})
					.then(function(bridgeInformation)
					{
						resolve(bridgeInformation);
					});
				}
				else if(scope.lastBridgeInformation !== null)
				{
					let bridgeInformationCopy = Object.assign({}, scope.lastBridgeInformation);
					resolve(bridgeInformationCopy);
				}
				else
				{
					let bridgeInformation = bridge.get("bridge", "bridge", { autoupdate: ((bridge.config.autoupdates && bridge.config.autoupdates == true) || typeof bridge.config.autoupdates == 'undefined') });
					scope.lastBridgeInformation = Object.assign({}, bridgeInformation);

					resolve(bridgeInformation);
				}
			});
		}

		bridge.subscribe("bridge", "globalRessourceUpdates", async function(info)
		{
			let currentState = bridge.get(info.updatedType, info.id);

			if(currentState !== false)
			{
				if(info.suppressMessage === false)
				{
					scope.status({fill: "blue", shape: "dot", text: "hue-bridge.node.connected"});

					if(scope.timeout !== null) { clearTimeout(scope.timeout); }
					scope.timeout = setTimeout(function() {
						scope.setInitialState();
					}, 1000);
				}

				if(!config.skipglobalevents && (config.initevents || info.suppressMessage == false))
				{
					scope.getBridgeInformation()
					.then(function(info)
					{
						info.updated = currentState;

						if(scope.lastCommand !== null)
						{
							info.command = scope.lastCommand;
						}

						scope.send(info);

						scope.lastCommand = null;
					});
				}
			}

			if(scope.connected == false)
			{
				scope.connected = true;
				scope.setInitialState();
			}
		});

		this.on('input', function(msg, send, done)
		{
			send = send || function() { scope.send.apply(scope,arguments); }
			done = done || function() { scope.done.apply(scope,arguments); }

			scope.lastCommand = msg;

			scope.getBridgeInformation()
			.then(function(bridgeInformation)
			{
				if(typeof msg.payload != 'undefined' && typeof msg.payload.touchLink != 'undefined')
				{
					scope.status({fill: "yellow", shape: "dot", text: "hue-bridge.node.starting-tl" });

					bridge.patch("bridge", "/config", { touchlink: true }, 1)
					.then(function(status)
					{
						scope.status({fill: "blue", shape: "ring", text: "hue-bridge.node.started-tl" });
						if(done) { done(); }

						setTimeout(function()
						{
							scope.setInitialState();
							scope.getBridgeInformation(true);
						}, 30000);
					})
					.catch(function(error)
					{
						scope.error(error);
						if(done) { done(error); }
					});
				}
				else if(typeof msg.payload != 'undefined' && typeof msg.payload.fetch != 'undefined')
				{
					let fetchTypes = [];
					if(typeof msg.payload.fetch == 'string') { fetchTypes.push(msg.payload.fetch); }
					else if(typeof msg.payload.fetch == 'object') { fetchTypes = msg.payload.fetch; }
					else { return false; }

					scope.status({fill: "blue", shape: "dot", text: "hue-bridge.node.f-ressources" });

					bridgeInformation.results = {};
					fetchTypes.forEach(function(fetch)
					{
						bridgeInformation.results[fetch] = bridge.get(fetch);
					});

					if(scope.lastCommand !== null)
					{
						bridgeInformation.command = scope.lastCommand;
					}

					send(bridgeInformation);

					scope.lastCommand = null;
					if(done) { done(); }

					setTimeout(function(){ scope.setInitialState(); }, 2000);
				}
				else if(typeof msg.payload != 'undefined' && typeof msg.payload.settings != 'undefined')
				{
					let patchObject = {};

					if(typeof msg.payload.settings.name != 'undefined')
					{
						patchObject.name = msg.payload.settings.name;
					}
					if(typeof msg.payload.settings.zigbeeChannel != 'undefined')
					{
						patchObject.zigbeechannel = msg.payload.settings.zigbeeChannel;
					}
					if(typeof msg.payload.settings.ipAddress != 'undefined')
					{
						patchObject.ipaddress = msg.payload.settings.ipAddress;
					}
					if(typeof msg.payload.settings.dhcpEnabled != 'undefined')
					{
						patchObject.dhcp = msg.payload.settings.dhcpEnabled;
					}
					if(typeof msg.payload.settings.netmask != 'undefined')
					{
						patchObject.netmask = msg.payload.settings.netmask;
					}
					if(typeof msg.payload.settings.gateway != 'undefined')
					{
						patchObject.gateway = msg.payload.settings.gateway;
					}
					if(typeof msg.payload.settings.proxyPort != 'undefined')
					{
						patchObject.proxyport = msg.payload.settings.proxyPort;
					}
					if(typeof msg.payload.settings.proxyAddress != 'undefined')
					{
						patchObject.proxyaddress = msg.payload.settings.proxyAddress;
					}
					if(typeof msg.payload.settings.timeZone != 'undefined')
					{
						patchObject.timezone = msg.payload.settings.timeZone;
					}

					if(Object.values(patchObject).length > 0)
					{
						scope.status({fill: "yellow", shape: "dot", text: "hue-bridge.node.updating-settings" });

						bridge.patch("bridge", "/config", patchObject, 1)
						.then(function(patched)
						{
							return scope.getBridgeInformation(true);
						})
						.then(function(bridgeInformation)
						{
							scope.status({fill: "blue", shape: "dot", text: "hue-bridge.node.settings-updated" });

							if(scope.lastCommand !== null)
							{
								bridgeInformation.command = scope.lastCommand;
							}

							scope.send(bridgeInformation);

							scope.lastCommand = null;

							if(done) { done(); }
							setTimeout(function(){ scope.setInitialState(); }, 3000);
						})
						.catch(function(error) {
							scope.error(error);
							if(done) { done(error); }
						});
					}
				}
				else
				{
					if(scope.lastCommand !== null)
					{
						bridgeInformation.command = scope.lastCommand;
					}

					scope.send(bridgeInformation);

					scope.lastCommand = null;
				}
			});
		});
	}

function ViewController($scope, SharedService) {
    DEBUG.log('ViewController init');
    window.viewScope = $scope;
    $scope.view = {
        bucket: null, prefix: null, settings: null, objectCount: 0, keys_selected: [],
    };
    $scope.stop = false;

    $tb.on('click', 'a', (e) => {
        const { currentTarget: target } = e;
        e.preventDefault();
        DEBUG.log('target href:', target.href);
        DEBUG.log('target dataset:', JSON.stringify(target.dataset));

        if (target.dataset.s3 === 'folder') {
            SharedService.changeViewPrefix(target.dataset.s3key);
        } else if ($scope.view.settings.auth === 'anon') {
            window.open(target.href, '_blank');
        } else {
            const s3 = new AWS.S3();
            const params = {
                Bucket: $scope.view.settings.bucket, Key: target.dataset.s3key, Expires: 15,
            };
            DEBUG.log('params:', params);
            s3.getSignedUrl('getObject', params, (err, url) => {
                if (err) {
                    DEBUG.log('err:', err);
                    SharedService.showError(params, err);
                } else {
                    DEBUG.log('url:', url);
                    window.open(url, '_blank');
                }
            });
        }
        return false;
    });

    $bc.on('click', 'a', (e) => {
        DEBUG.log('breadcrumb li click');
        e.preventDefault();
        const { currentTarget: target } = e;
        DEBUG.log('target dataset:', JSON.stringify(target.dataset));
        SharedService.changeViewPrefix(target.dataset.prefix);
        return false;
    });

    $scope.$on('broadcastChangeSettings', (e, args) => {
        DEBUG.log('ViewController', 'broadcast change settings:', args.settings);
        $scope.view.objectCount = 0;
        $scope.view.settings = args.settings;
        $scope.refresh();
    });

    $scope.$on('broadcastChangePrefix', (e, args) => {
        DEBUG.log('ViewController', 'broadcast change prefix args:', args);
        $scope.$apply(() => {
            $scope.folder2breadcrumbs($scope.view.settings.bucket, args.viewprefix || args.prefix);

            if (args.viewprefix !== undefined && args.viewprefix !== null) {
                $.fn.dataTableExt.afnFiltering.length = 0;

                $.fn.dataTableExt.afnFiltering.push(
                    (_o, d, _i) => d[1] !== args.viewprefix && d[1].startsWith(args.viewprefix),
                );

                $tb.DataTable().draw();
            } else {
                $.fn.dataTableExt.afnFiltering.length = 0;
                $scope.view.settings.prefix = args.prefix;
                $scope.refresh();
            }
        });
    });

    $scope.$on('broadcastViewRefresh', () => {
        DEBUG.log('ViewController', 'broadcast view refresh');
        $scope.$apply(() => {
            $scope.refresh();
        });
    });

    $scope.renderObject = (data, _type, full) => {
        const href = object2hrefvirt($scope.view.settings.bucket, data);

        function render(d, href2, text, download) {
            const d2 = htmlEscape(d);
            if (download) {
                return `<a data-s3="object" data-s3key="${d2}" href="${href2}" download="${download}">${text}</a>`;
            }
            return `<a data-s3="folder" data-s3key="${d2}" href="${href2}">${text}</a>`;
        }

        if (full.CommonPrefix) {
            if ($scope.view.settings.prefix) {
                return render(data, href, prefix2folder(data));
            }

            return render(data, href, data);
        }

        return render(data, href, fullpath2filename(data), fullpath2filename(data));
    };

    $scope.renderFolder = (data, _type, full) => (full.CommonPrefix ? '' : fullpath2pathname(data));

    $scope.progresscb = (objects, folders) => {
        DEBUG.log('ViewController', 'Progress cb objects:', objects);
        DEBUG.log('ViewController', 'Progress cb folders:', folders);
        $scope.$apply(() => {
            $scope.view.objectCount += objects + folders;
        });
    };

    $scope.refresh = () => {
        DEBUG.log('refresh');
        if ($scope.running()) {
            DEBUG.log('running, stop');
            $scope.listobjectsstop();
        } else {
            DEBUG.log('refresh', $scope.view.settings);
            $scope.view.objectCount = 0;
            $scope.folder2breadcrumbs(
                $scope.view.settings.bucket,
                SharedService.getViewPrefix(),
            );
            $scope.listobjects(
                $scope.view.settings.bucket,
                $scope.view.settings.prefix,
                $scope.view.settings.delimiter,
            );
        }
    };

    $scope.upload = () => {
        DEBUG.log('Add files');
        $('#addedFiles').trigger('click');
    };

    $scope.trash = () => {
        DEBUG.log('Trash:', $scope.view.keys_selected);
        if ($scope.view.keys_selected.length > 0) {
            SharedService.trashObjects($scope.view.settings.bucket, $scope.view.keys_selected);
        }
    };

    $scope.running = () => $bl.hasClass('fa-spin');

    $scope.folder2breadcrumbs = (bucket, prefix) => {
        DEBUG.log('Breadcrumbs bucket:', bucket);
        DEBUG.log('Breadcrumbs prefix:', prefix);

        $('#breadcrumb li').remove();

        const prefixes = [''];
        let buildprefix = '';

        if (prefix) {
            prefixes.push(...prefix.replace(/\/$/g, '').split('/'));
        }

        for (let ii = 0; ii < prefixes.length; ii++) {
            let li;

            if (ii === 0) {
                const a1 = $('<a>').attr('href', '#').text(bucket);
                li = $('<li>').append(a1);
            } else if (ii < prefixes.length - 1) {
                const a2 = $('<a>').attr('href', '#').text(prefixes[ii]);
                li = $('<li>').append(a2);
            } else {
                li = $('<li>').text(prefixes[ii]);
            }

            if (ii) {
                buildprefix = `${buildprefix}${prefixes[ii]}/`;
            }

            li.children('a').attr('data-prefix', buildprefix).attr('data-bucket', bucket);

            $bc.append(li);
        }

        $('#breadcrumb li:last').addClass('active');
    };

    $scope.listobjectsstop = (stop) => {
        DEBUG.log('ViewController', 'listobjectsstop:', stop || true);
        $scope.stop = stop || true;
    };

    $scope.listobjectscb = (err, data) => {
        DEBUG.log('Enter listobjectscb');
        if (err) {
            DEBUG.log('Error:', JSON.stringify(err));
            DEBUG.log('Error:', err.stack);
            $bl.removeClass('fa-spin');
            const params = { bucket: $scope.view.bucket, prefix: $scope.view.prefix };
            SharedService.showError(params, err);
        } else {
            let marker;

            if (data.IsTruncated) {
                if (data.NextMarker) {
                    marker = data.NextMarker;
                } else if (data.Contents.length > 0) {
                    marker = data.Contents[data.Contents.length - 1].Key;
                }
            }

            const count = { objects: 0, folders: 0 };

            $.each(data.Contents, (index, value) => {
                if (value.Key === data.Prefix) {
                } else if (isfolder(value.Key)) {
                    $tb.DataTable().row.add({
                        CommonPrefix: true, Key: value.Key, StorageClass: null,
                    });
                    count.folders++;
                } else {
                    $tb.DataTable().row.add(value);
                    count.objects++;
                }
            });

            $.each(data.CommonPrefixes, (index, value) => {
                $tb.DataTable().rows.add([
                    { CommonPrefix: true, Key: value.Prefix, StorageClass: null },
                ]);
                count.objects++;
            });

            $tb.DataTable().draw();

            $scope.progresscb(count.objects, count.folders);

            const params = {
                Bucket: data.Name, Prefix: data.Prefix, Delimiter: data.Delimiter, Marker: marker,
            };


            if ($scope.stop) {
                DEBUG.log('Bucket', data.Name, 'stopped');
                $bl.removeClass('fa-spin');
            } else if (data.IsTruncated) {
                DEBUG.log('Bucket', data.Name, 'truncated');
                const s3 = new AWS.S3(AWS.config);
                if (AWS.config.credentials && AWS.config.credentials.accessKeyId) {
                    DEBUG.log('Make S3 authenticated call to listObjects');
                    s3.listObjects(params, $scope.listobjectscb);
                } else {
                    DEBUG.log('Make S3 unauthenticated call to listObjects');
                    s3.makeUnauthenticatedRequest('listObjects', params, $scope.listobjectscb);
                }
            } else {
                DEBUG.log('Bucket', data.Name, 'listing complete');
                $bl.removeClass('fa-spin');
            }
        }
    };

    $scope.listobjects = (Bucket, Prefix, Delimiter, Marker) => {
        DEBUG.log('Enter listobjects');

        if (!Marker) {
            $scope.stop = false;

            $scope.view.keys_selected = [];
            $bl.addClass('fa-spin');
            $tb.DataTable().clear();
            $tb.DataTable().column(s3ExplorerColumns.folder).visible(!Delimiter);
        }

        const s3 = new AWS.S3(AWS.config);
        const params = {
            Bucket, Prefix, Delimiter, Marker,
        };


        if (AWS.config.credentials && AWS.config.credentials.accessKeyId) {
            DEBUG.log('Make S3 authenticated call to listObjects, params:', params);
            s3.listObjects(params, $scope.listobjectscb);
        } else {
            DEBUG.log('Make S3 unauthenticated call to listObjects, params:', params);
            s3.makeUnauthenticatedRequest('listObjects', params, $scope.listobjectscb);
        }
    };

    this.isfolder = path => path.endsWith('/');

    this.renderSelect = (data, type, _full) => {
        if (type === 'display') {
            return '<span class="text-center"><input type="checkbox"></span>';
        }

        return '';
    };

    this.renderObject = (data, type, full) => {
        if (type === 'display') {
            return $scope.renderObject(data, type, full);
        }

        return data;
    };

    this.renderFolder = (data, type, full) => $scope.renderFolder(data, type, full);

    this.renderLastModified = (data, _type, _full) => {
        if (data) {
            return moment(data).fromNow();
        }

        return '';
    };

    this.renderTimestamp = (data, _type, _full) => {
        if (data) {
            return moment(data).local().format('YYYY-MM-DD HH:mm:ss');
        }

        return '';
    };

    this.renderStorageClass = (data, _type, _full) => {
        if (data) {
            return mapStorage[data];
        }

        return '';
    };

    this.dataSize = (source, type, _val) => {
        if (source.Size) {
            return (type === 'display') ? bytesToSize(source.Size) : source.Size;
        }

        return '';
    };

    $tb.DataTable({
        iDisplayLength: 25,
        order: [[2, 'asc'], [1, 'asc']],
        aoColumnDefs: [
            {
                aTargets: [0], mData: null, mRender: this.renderSelect, sClass: 'text-center', sWidth: '20px', bSortable: false,
            },
            {
                aTargets: [1], mData: 'Key', mRender: this.renderObject, sType: 'key',
            },
            {
                aTargets: [2], mData: 'Key', mRender: this.renderFolder,
            },
            {
                aTargets: [3], mData: 'LastModified', mRender: this.renderLastModified,
            },
            {
                aTargets: [4], mData: 'LastModified', mRender: this.renderTimestamp,
            },
            {
                aTargets: [5], mData: 'StorageClass', mRender: this.renderStorageClass,
            },
            {
                aTargets: [6], mData: this.dataSize,
            },
        ],
    });

    $.fn.dataTableExt.oSort['key-asc'] = (a, b) => {
        const x = (isfolder(a) ? `0-${a}` : `1-${a}`).toLowerCase();
        const y = (isfolder(b) ? `0-${b}` : `1-${b}`).toLowerCase();
        if (x < y) return -1;
        if (x > y) return 1;
        return 0;
    };

    $.fn.dataTableExt.oSort['key-desc'] = (a, b) => {
        const x = (isfolder(a) ? `1-${a}` : `0-${a}`).toLowerCase();
        const y = (isfolder(b) ? `1-${b}` : `0-${b}`).toLowerCase();
        if (x < y) return 1;
        if (x > y) return -1;
        return 0;
    };

    $('#s3objects-table tbody').on('click', 'input[type="checkbox"]', (e1) => {
        const checkbox = e1.currentTarget;
        const $row = $(checkbox).closest('tr');
        const data = $tb.DataTable().row($row).data();
        let index = -1;

        e1.stopPropagation();

        index = $scope.view.keys_selected.findIndex(e2 => e2.Key === data.Key);

        if (checkbox.checked && index === -1) {
            $scope.view.keys_selected.push(data);
        } else if (!checkbox.checked && index !== -1) {
            $scope.view.keys_selected.splice(index, 1);
        }

        $scope.$apply(() => {
            DEBUG.log('Selected rows:', $scope.view.keys_selected);
        });

        if (checkbox.checked) {
            $row.addClass('selected');
        } else {
            $row.removeClass('selected');
        }
    });

    $('#s3objects-table tbody').on('click', 'td', (e) => {
        $(e.currentTarget).parent().find('input[type="checkbox"]').trigger('click');
    });
}

function getExifEl() {
    var el = getEl('fittr-exif-dislay');
    if (!el) {
      el = createEl('div');
      el.id = 'fittr-exif-dislay';
      el.innerHTML = '<i>Loading</i>';
      link.parentNode.parentNode.insertBefore(el, link.parentNode.nextSibling);

      api.makeApiRequest(api.RequestType.GET_EXIF, {photo_id: page.getPhotoId()}, function(data) {
        if (data.status == 200 && data.content.stat == 'ok') {
          var html = '<table class="fittr-exif-table">';
          var seen = {};
          for (var i = 0; i < data.content.photo.exif.length; i++) {
            var item = data.content.photo.exif[i];
            if (item.tag in EXIF_TAG_WHITELIST && !(item.tag in seen)) {
              seen[item.tag] = 1;
              var value = item.clean ? item.clean._content : item.raw._content;
              html += '<tr><td>' + item.label + '</td><td>' + value + '</td></tr>';
            }
          }
          html += '</table>';
          el.innerHTML = html;
        } else if (data.status == 200 && data.content.stat == 'fail') {
          el.innerHTML = '<i>Error loading EXIF : ' + data.content.message + '</i>';
        } else {
          el.innerHTML = '<i>Error loading EXIF.</i>';
        }
        el.style.height = el.scrollHeight + 'px';
      });
    }
    return el;
  }

function validateLink(url) {

  var str      = url.trim().toLowerCase(),
      protocol = str.split(':')[0];

  if (str.indexOf(':') >= 0 && BAD_PROTOCOLS.indexOf(protocol) >= 0) {
    if (protocol === 'data' && ALLOWED_DATA_MIMES.indexOf(str.split(';')[0]) >= 0) {
      return true;
    }
    return false;
  }

  return true;
}

function barrettReduce(x) {
  x.drShiftTo(this.m.t-1,this.r2);
  if(x.t > this.m.t+1) { x.t = this.m.t+1; x.clamp(); }
  this.mu.multiplyUpperTo(this.r2,this.m.t+1,this.q3);
  this.m.multiplyLowerTo(this.q3,this.m.t+1,this.r2);
  while(x.compareTo(this.r2) < 0) x.dAddOffset(1,this.m.t+1);
  x.subTo(this.r2,x);
  while(x.compareTo(this.m) >= 0) x.subTo(this.m,x);
}

